CREATE TABLE IF NOT EXISTS ml_kad (anorm TEXT PRIMARY KEY, kad_nr TEXT NOT NULL DEFAULT '', dati TEXT NOT NULL DEFAULT '{}', raw TEXT NOT NULL DEFAULT '',
  avots TEXT NOT NULL DEFAULT '', atjaunots TEXT NOT NULL DEFAULT '', kas TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS ml_doc (id TEXT PRIMARY KEY, anorm TEXT NOT NULL, nosaukums TEXT NOT NULL DEFAULT '', tips TEXT NOT NULL DEFAULT '', r2 TEXT NOT NULL DEFAULT '',
  izmers INTEGER NOT NULL DEFAULT 0, pievienoja TEXT NOT NULL DEFAULT '', laiks TEXT NOT NULL DEFAULT '', dzests INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS ml_doc_a ON ml_doc (anorm);
CREATE TABLE IF NOT EXISTS ml_log (id INTEGER PRIMARY KEY AUTOINCREMENT, laiks TEXT NOT NULL, teksts TEXT NOT NULL);
